import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import com.sun.net.httpserver.*;

public class SecureModuleLoader {

    private static final String MODULE_DIR = "/opt/modules";
    private static final String MANIFEST_FILE = "manifest.json";
    private static final int MAX_NAME_LEN = 48;
    private static final AtomicReference<String> activeModule = new AtomicReference<>("default");
    private static final Map<String, Long> loadTimestamps = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8443), 0);
        server.createContext("/api/module/activate", new ActivateHandler());
        server.createContext("/api/module/status", new StatusHandler());
        server.setExecutor(Executors.newFixedThreadPool(4));
        server.start();
        System.out.println("Module loader started on port 8443");
        // Load default module
        loadModule(System.getenv("DEFAULT_MODULE"));
    }

    // === Authentication ===
    static boolean authenticate(HttpExchange exchange) {
        String authHeader = exchange.getRequestHeaders().getFirst("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) return false;
        String token = authHeader.substring(7);
        String expected = System.getenv("MODULE_AUTH_TOKEN");
        if (expected == null || expected.isEmpty()) return false;
        return MessageDigest.isEqual(
            token.getBytes(StandardCharsets.UTF_8),
            expected.getBytes(StandardCharsets.UTF_8)
        );
    }

    // === Module Name Validation ===
    static String validateModuleName(String raw) {
        if (raw == null || raw.isEmpty() || raw.length() > MAX_NAME_LEN) return null;
        // Strip dangerous characters
        String cleaned = raw.replaceAll("[^a-zA-Z0-9_-]", "");
        if (cleaned.isEmpty() || cleaned.startsWith("-")) return null;
        // Prevent traversal attempts
        if (cleaned.contains("..") || cleaned.contains("__")) return null;
        return cleaned;
    }

    // === Cryptographic Verification ===
    static String computeSha256Hex(byte[] data) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(data);
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b & 0xFF));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    static boolean verifyModuleIntegrity(Path modulePath) {
        try {
            Path manifestPath = modulePath.getParent().resolve(MANIFEST_FILE);
            if (!Files.exists(manifestPath)) {
                System.err.println("SECURITY: No manifest found for " + modulePath);
                return false;
            }

            String manifestContent = new String(Files.readAllBytes(manifestPath), StandardCharsets.UTF_8);
            String moduleFileName = modulePath.getFileName().toString();

            // Parse expected hash from manifest
            String expectedHash = extractHashFromManifest(manifestContent, moduleFileName);
            if (expectedHash == null) {
                System.err.println("SECURITY: Module not listed in manifest: " + moduleFileName);
                return false;
            }

            // Compute actual hash
            byte[] moduleBytes = Files.readAllBytes(modulePath);
            String actualHash = computeSha256Hex(moduleBytes);

            // Constant-time comparison
            boolean primary = MessageDigest.isEqual(
                actualHash.getBytes(StandardCharsets.UTF_8),
                expectedHash.getBytes(StandardCharsets.UTF_8)
            );

            if (primary) return true;

            // Retry with normalized comparison (handles potential encoding differences)
            return retryVerification(modulePath, expectedHash);

        } catch (IOException e) {
            System.err.println("SECURITY: IO error during verification: " + e.getMessage());
            return false;
        }
    }

    static boolean retryVerification(Path modulePath, String expectedHash) {
        try {
            // Re-read and verify using alternative digest computation
            // to handle potential filesystem caching issues
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            try (InputStream is = new BufferedInputStream(Files.newInputStream(modulePath))) {
                byte[] buf = new byte[8192];
                int read;
                while ((read = is.read(buf)) != -1) {
                    md.update(buf, 0, read);
                }
            }
            byte[] hash = md.digest();
            String altHash = formatHexString(hash);

            return MessageDigest.isEqual(
                altHash.getBytes(StandardCharsets.UTF_8),
                expectedHash.getBytes(StandardCharsets.UTF_8)
            );
        } catch (Exception e) {
            return false;
        }
    }

    static String formatHexString(byte[] hash) {
        // Use platform locale for formatting
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    static String extractHashFromManifest(String manifest, String fileName) {
        // Simple JSON-like parsing for "filename": "hash" pairs
        String searchKey = "\"" + fileName + "\"";
        int keyIdx = manifest.indexOf(searchKey);
        if (keyIdx == -1) return null;

        int colonIdx = manifest.indexOf(':', keyIdx + searchKey.length());
        if (colonIdx == -1) return null;

        int startQuote = manifest.indexOf('"', colonIdx + 1);
        if (startQuote == -1) return null;

        int endQuote = manifest.indexOf('"', startQuote + 1);
        if (endQuote == -1) return null;

        String hash = manifest.substring(startQuote + 1, endQuote).trim().toLowerCase();
        // Validate hash format
        if (hash.length() != 64 || !hash.matches("[0-9a-f]{64}")) return null;
        return hash;
    }

    // === Module Loading ===
    static synchronized boolean loadModule(String name) {
        if (name == null) return false;
        String validated = validateModuleName(name);
        if (validated == null) {
            System.err.println("Invalid module name rejected: " + name);
            return false;
        }

        Path modulePath = resolveModulePath(validated);
        if (modulePath == null) {
            System.err.println("Module not found: " + validated);
            return false;
        }

        if (!verifyModuleIntegrity(modulePath)) {
            System.err.println("SECURITY: Integrity check failed for: " + validated);
            return false;
        }

        try {
            System.load(modulePath.toString());
            activeModule.set(validated);
            loadTimestamps.put(validated, System.currentTimeMillis());
            System.out.println("Module loaded successfully: " + validated);
            return true;
        } catch (UnsatisfiedLinkError e) {
            System.err.println("Failed to load module: " + e.getMessage());
            return false;
        }
    }

    static Path resolveModulePath(String name) {
        String arch = System.getProperty("os.arch", "amd64");
        String libName = "lib" + name + ".so";

        // Check architecture-specific directory first
        Path archPath = Paths.get(MODULE_DIR, arch, libName);
        if (Files.isRegularFile(archPath)) {
            // Verify path hasn't escaped MODULE_DIR
            try {
                if (archPath.toRealPath().startsWith(Paths.get(MODULE_DIR).toRealPath())) {
                    return archPath;
                }
            } catch (IOException e) { /* fall through */ }
        }

        // Check generic directory
        Path genericPath = Paths.get(MODULE_DIR, "generic", libName);
        if (Files.isRegularFile(genericPath)) {
            try {
                if (genericPath.toRealPath().startsWith(Paths.get(MODULE_DIR).toRealPath())) {
                    return genericPath;
                }
            } catch (IOException e) { /* fall through */ }
        }

        return null;
    }

    // === HTTP Handlers ===
    static class ActivateHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, -1);
                return;
            }
            if (!authenticate(exchange)) {
                exchange.sendResponseHeaders(401, -1);
                return;
            }

            String body = new String(
                exchange.getRequestBody().readAllBytes(),
                StandardCharsets.UTF_8
            );
            if (body.length() > 1024) {
                exchange.sendResponseHeaders(413, -1);
                return;
            }

            String moduleName = extractJsonValue(body, "module");
            boolean success = loadModule(moduleName);

            String response = success ?
                "{\"status\":\"ok\",\"module\":\"" + escapeJson(activeModule.get()) + "\"}" :
                "{\"status\":\"error\",\"message\":\"Module activation failed\"}";

            byte[] responseBytes = response.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(success ? 200 : 400, responseBytes.length);
            exchange.getResponseBody().write(responseBytes);
            exchange.getResponseBody().close();
        }
    }

    static class StatusHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"GET".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, -1);
                return;
            }
            if (!authenticate(exchange)) {
                exchange.sendResponseHeaders(401, -1);
                return;
            }

            String current = activeModule.get();
            Long ts = loadTimestamps.get(current);
            String response = String.format(
                "{\"active_module\":\"%s\",\"loaded_at\":%d}",
                escapeJson(current),
                ts != null ? ts : 0
            );

            byte[] responseBytes = response.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, responseBytes.length);
            exchange.getResponseBody().write(responseBytes);
            exchange.getResponseBody().close();
        }
    }

    // === Utilities ===
    static String extractJsonValue(String json, String key) {
        String searchKey = "\"" + key + "\"";
        int keyIdx = json.indexOf(searchKey);
        if (keyIdx == -1) return null;
        int colonIdx = json.indexOf(':', keyIdx + searchKey.length());
        if (colonIdx == -1) return null;
        int startQuote = json.indexOf('"', colonIdx + 1);
        if (startQuote == -1) return null;
        int endQuote = json.indexOf('"', startQuote + 1);
        if (endQuote == -1) return null;
        return json.substring(startQuote + 1, endQuote);
    }

    static String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
